<script language="JavaScript1.2" src="../scripts/validar.js?1"></script><body>	<?$Table = "Empleado";$Key = "IDEmpleado";$MOD = $mod;?><?		$permisos = get_permiso($ID_Usuario,$m,$Table);if($permisos[0] >= 2){		switch (nvl($action)) {					case "add" :				$usr=$_POST[Usuarios];				addalista($usr,"RestriccionxUsuario",$IDGrupo,$IDUsuario,$modulo);			break;			case "list" :				$sql = make_qry_string($HTTP_GET_VARS);				list_usr($sql);			break;									default : 					list_usr();			break;				} // End switch}//end if permisos	/*******************************************************************************************		funcion Listar*******************************************************************************************/	function list_usr($sql=""){		Global $TitleMod,$MOD,$Table,$Key,$id,$vergrupousr,$tabla_grupo,$msg_rol;		Global $idnot,$tabla_existe,$IDGrupo,$IDUsuario;		$tabla_existe = "RestriccionxUsuario";		?>				<script> 		function ChequearTodos(chkbox) 		{ 			for (var i=0;i < document.forms[0].elements.length;i++)			 { 				var elemento = document.forms[0].elements[i]; 				if (elemento.type == "checkbox")				 { 					elemento.checked = chkbox.checked 					}			 } 		} 		</script>	<?	if(empty($sql))	 	//$sql =  "SELECT * FROM Empleado D $from WHERE D.Nivel<>0 $condicionGrupo $groupby ORDER BY D.Nombre";	 	$sql =  "SELECT * FROM Empleado WHERE Nivel<>0 ORDER BY Nombre";	 			$nav = new buildNav;		$nav->offset = 'offset';   		$nav->number_type = 'number';   		$nav->limit = 15;   		$nav->execute($sql,$dblink);		$total_records =  $nav->total_result;		$rows = $nav->rows;		$result = $nav->sql_result;		$row = $offset;		$startrow = $offset + 1;		$finalrow = ($row * $nav->limit) + $rows;		 	$pages = $nav->show_num_pages('&laquo;','&laquo; prev','&raquo;','next &raquo;','|','class=navvar');   // show pages				$info = $nav->show_info(); 		?>			<?		if($rows > 0){		?>	<table  width="600" cellpadding=0 cellspacing=0  class=tablas>		<form name="formulario" action="" method="post">			<%if($msg_rol){%>			<tr class=row2>				<td colspan="2"><%=Mensaje_Info("Si el usuario ya hace parte de un rol, no podr&aacute; ser agregado a este nuevo rol.","textos")%></td>			</tr>			<%}//end if%>			<tr>				<td>					<table width=100% border=0 cellspacing=1 cellpadding=0>						<tr >							<td width="20" align="center"  class=maintitle valign=middle bgcolor=#DBEAF5 width=69>								<input type="checkbox" name="checkall" value="checkbox" onclick="ChequearTodos(this);">							</td>							<td class=maintitle width="80">Nombre</td>							<td class=maintitle width="100">Apellido</td>							<%if($vergrupousr){%>							<td class=maintitle width="100">Rol</td>							<%}%>						</tr>						<? while($r = db_fetch_object($result)){						$class = repetition()?"row1":"row2";						?> 						<tr>							<td width="20" align="center" valign=middle nowrap width=50 class=<?=$class?>>								<input type="checkbox" name="Usuarios[<?=$r->IDEmpleado?>]" value="<?=$r->IDEmpleado?>">							</td>							<td nowrap class=<?=$class?> width="80"><? echo $r->Nombre?></td>							<td nowrap class=<?=$class?> width="100"><? echo $r->Apellidos?></td>							<%if($vergrupousr){%>							<td nowrap class=<?=$class?> width="100"><? 							$IDGrupoUsuarios = get_field("$tabla_existe","$IDGrupo","$IDUsuario",$r->$IDUsuario);							echo get_field("$tabla_grupo","Nombre","$IDGrupo",$IDGrupoUsuarios)?></td>							<%}%>						</tr>		<? } // END for ?>						<tr>							<td class=texto colspan=4 nowrap width="352">								<?	print $pages; ?>							</td>						</tr>						<tr>							<td class=texto colspan="4" align="center" bgcolor=#788198 nowrap width="352">								<input type="hidden" name="mod" value="<?=$MOD?>">								<input type="hidden" name="id" value="<?=$id?>">								<input type=hidden name=action value="add">								<input type=submit name=submit value="A&ntilde;adir contactos seleccionados" class=submit></td>						</tr>					</table>				</td>												</form>			</tr>			</table><? 			}// End if$rowselse	echo "<br><br><span class=subtitle><b>No existen registros en  $TitleMod </b></span><br>";filtrar();	}// Enf function list()				?><?/*******************************************************************************************		funcion filtrar*******************************************************************************************/	function filtrar(){	Global $dblink,$total_records,$row,$numtoshow,$MOD,$id,$idnot;?><script>var Check = new Array("QryString","field");</script>			<table width="600" border="0"  cellspacing="1" cellpadding="0" bgcolor="#345487">			<form name="frm" action="./" method="get" onsubmit="return valbuscar(document.frm)">			<tr>				<td class="rowform" align="center" colspan=8>					<select name="field" id="Buscar Por" class="popup">						<option value="">Buscar Por</option>						<option value="Nombre">Nombre</option>						<option value="Apellidos">Apellidos</option>					</select> <input type="text" size="20" name="QryString" id="Buscar Por" class="post"> ordenar por <select name="order_by" class="popup">						<option value="Nombre">Nombre</option>						<option value="Apellidos">Apellidos</option>					</select>					de forma <select name="in_order" class="popup">						<option value="ASC">Ascendente</option>						<option value="DESC">Descendente</option>					</select><br>					<input type="hidden" name="mod" value="<?=$MOD?>">					<input type="hidden" name="id" value="<?=$id?>">					<input type="hidden" name="idnot" value="<?=$idnot?>">					<input type="hidden" name="rangofield" value="Fecha">					<input type="hidden" name="action" value="list">					<input type="submit" name="submit" value="Buscar" class="submit">				</td>			</tr>				</form>		</table><?			}//End function filtrar?><?/****************************************************************************** * FUNCTIONS *****************************************************************************//*******************************************************************************************		funcion addalista($frm)*******************************************************************************************/function addalista($usu,$tabla_existe, $IDGrupo, $IDUsuario,$modulo){	GLOBAL $TitleMod,$Table,$MOD,$Key,$idnot,$id,$repetir;	$tabla_existe = "RestriccionxUsuario";	$ruta = "&id=".$id;	if(!$id){		$id=$idnot;		$ruta = "&idnot=".$id;	}	?>	<?		if(!empty($idnot))	{		foreach($usu as $key=>$valor)		{			$qry_existe= db_query("SELECT * FROM $tabla_existe WHERE $IDGrupo ='$id' AND $IDUsuario=$valor");			if(db_num_rows($qry_existe)<1){				if(!$repetir)					if(db_num_rows(db_query("SELECT * FROM $tabla_existe WHERE $IDUsuario=$valor")))						continue;				db_query("INSERT INTO $tabla_existe ($IDGrupo,$IDUsuario) VALUES ('$id','$valor')");			}		}		?>	<script language="JavaScript"> 					location.href='<%echo "?mod=$MOD$ruta" %>';				</script>		<?	}	else		{		echo("<center>No selecciono una lista <br>");		echo("<a href=\"javascript:history.go(-1)\" title=\"Pagina Anterior\"><< Pagina Anterior</a></center>");		}}?>